TC_CATALOG_BY_ITEM = {}
for spellId, data in pairs(TC_CATALOG) do
    if data.item and data.item > 0 then
        TC_CATALOG_BY_ITEM[data.item] = {
            spellId = spellId,
            name = data.name,
            icon = data.icon,
            type = data.type,
            level = data.level
        }
    end
end

-- Alternate item mappings for identical spells
local altItems = {
    [81120] = 46451, [50073] = 10801, [12354] = 16082, [8592] = 10799,
    [92052] = 57577, [12353] = 16083, [80002] = 45016, [69005] = 49513,
    [83010] = 49505, [50006] = 46458, [46497] = 46496, [80456] = 45044
}
for iId, sId in pairs(altItems) do
    if TC_CATALOG[sId] and not TC_CATALOG_BY_ITEM[iId] then
        local base = TC_CATALOG[sId]
        TC_CATALOG_BY_ITEM[iId] = {
            spellId = sId,
            name = base.name,
            icon = base.icon,
            type = base.type,
            level = base.level
        }
    end
end
